function weddingMomentsSection(lang){const w=weddingMoments[lang];return `<section class="section unified-weddings" id="celebrations"><div class="wrap"><span class="eyebrow section-label">${w.label}</span><div class="section-head"><h2>${w.title}</h2><p>${w.intro}</p></div><div class="offer-grid">${w.moments.map((x,i)=>`<article class="offer-card"><img src="/images/${['mojito-event-640','wedding-coast-640','citrus-cocktail'][i]}.webp" width="600" height="450" alt="" loading="lazy" decoding="async"><h3>${x[0]}</h3><p>${x[1]}</p><a class="text-link" href="#event-contact" data-event-project="0" data-wedding-moment="${i}">${w.cta} <span aria-hidden="true">↗</span></a></article>`).join('')}</div><p class="section-note">${w.note}</p></div></section>`;}
